def transform(g):
    H=len(g);W=len(g[0]);out=[r[:] for r in g]
    seen=[[False]*W for _ in range(H)];lab=[[-1]*W for _ in range(H)];boxes=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==0 or seen[r][c]: continue
            col=g[r][c];st=[(r,c)];comp=[];seen[r][c]=True
            while st:
                x,y=st.pop();comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<H and 0<=b<W and not seen[a][b] and g[a][b]==col:
                        seen[a][b]=True;st.append((a,b))
            k=len(boxes)
            rs=[p[0] for p in comp];cs=[p[1] for p in comp]
            boxes.append((min(rs),max(rs),min(cs),max(cs)))
            for x,y in comp: lab[x][y]=k
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0: continue
            ks=set()
            for a,b in ((r,c-1),(r,c+1),(r-1,c),(r+1,c)):
                if 0<=a<H and 0<=b<W and lab[a][b]>=0: ks.add(lab[a][b])
            if c>0 and c+1<W and g[r][c-1]==g[r][c+1]!=0:
                for k in ks:
                    mr,Mr,mc,Mc=boxes[k]
                    if Mc-mc>=Mr-mr: out[r][c]=g[r][c-1]
                    break
            elif r>0 and r+1<H and g[r-1][c]==g[r+1][c]!=0:
                for k in ks:
                    mr,Mr,mc,Mc=boxes[k]
                    if Mr-mr>=Mc-mc: out[r][c]=g[r-1][c]
                    break
    return out
